 * bootstrap intervals use the tool's own 2000 draws and seed 17017.
 * Regenerate with `parity/generate_leaf_vectors.py`.
 */
internal object LeafVectors {
    const val PYTHON_REVISION: String = "233edd085db9427e7feb19fd150d504b5d43be1b"

    private val chunks: List<String> = listOf(
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    )

    val json: String by lazy { chunks.joinToString("").decodeBase64()!!.utf8() }
}
